using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.IO;
public static class NatureSample {
 [MenuItem("Vampire Demo/Build Nature Sample")]
 public static void Run(){var s=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var ground=GameObject.CreatePrimitive(PrimitiveType.Plane);ground.transform.localScale=new Vector3(4,1,2);var sun=new GameObject("Sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.3f;sun.transform.rotation=Quaternion.Euler(50,-30,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=Color.gray;
 string[] paths={"Assets/Forst/Conifers [BOTD]/Render Pipeline Support/URP/Prefabs/PF Conifer Tall BOTD URP.prefab","Assets/Forst/Conifers [BOTD]/Render Pipeline Support/URP/Prefabs/PF Conifer Medium BOTD URP.prefab","Assets/Polyeler/EssentialNaturePack/Prefabs/Pine.prefab","Assets/Polyeler/EssentialNaturePack/Prefabs/JapaneseLaurel.prefab","Assets/Polyeler/EssentialNaturePack/Prefabs/Rock_A.prefab","Assets/Polyeler/EssentialNaturePack/Prefabs/Decayed_wood_A.prefab","Assets/Fantasy Forest Environment Free Sample/Meshes/Prefabs/tree_1.prefab","Assets/Fantasy Forest Environment Free Sample/Meshes/Prefabs/grass01.prefab"};
 for(int i=0;i<paths.Length;i++){var p=AssetDatabase.LoadAssetAtPath<GameObject>(paths[i]);if(!p){Debug.LogError("Missing "+paths[i]);continue;}var o=(GameObject)PrefabUtility.InstantiatePrefab(p);o.transform.position=new Vector3((i%4-1.5f)*8,0,(i/4)*8);var rs=o.GetComponentsInChildren<Renderer>();foreach(var r in rs)foreach(var m in r.sharedMaterials)if(m && m.shader && !m.shader.isSupported)Debug.LogWarning("Unsupported "+paths[i]+" "+m.shader.name);}
 EditorSceneManager.SaveScene(s,"Assets/Demo/Scenes/NatureAssetSample.unity");Debug.Log("NATURE_SAMPLE_SAVED");}
}
